function finishBFinal(timeUp=false){
  if(!bFinalItems.length)return;
  stopBFinalTimer();
  clearBFinalResume();
  const used=Math.min(B_FINAL_SECONDS,Math.max(0,Math.round((Date.now()-(bFinalStartedAt||Date.now()))/1000)));
  let correct=0,blank=0,algoCorrect=0,secCorrect=0;
  const details=bFinalItems.map((item,i)=>{
    const ans=bFinalAnswers[i],ok=ans===item.a;if(ok){correct++;if(item.kind==='algo')algoCorrect++;else secCorrect++;}if(ans===null)blank++;
    const key=item.kind==='security'?`sec:${item.sourceId}`:`algo:${item.sourceId}`;
    if(!profile.bFinalStats[key])profile.bFinalStats[key]={seen:0,correct:0,lastSeen:null};
    const st=profile.bFinalStats[key];st.seen++;if(ok)st.correct++;st.lastSeen=localDateISO(0);
    const detail={sourceId:item.sourceId,kind:item.kind,format:bFinalFormatOf(item),domain:item.kind==='security'?(item.concept||'情報セキュリティ'):(item.domain||'擬似言語'),title:item.title,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain,studyMode:item.studyMode};
    if(!ok){const mk=bFinalMistakeKey(detail);const ms=profile.bFinalMistakeStats[mk]||(profile.bFinalMistakeStats[mk]={misses:0,reasons:{},lastReason:null,last:null});ms.misses=(ms.misses||0)+1;ms.last=localDateISO(0);}
    return detail;
  });
  // Internal legacy practice points are retained only for saved-data compatibility and XP logic.
  // The UI shows raw correct count/rate and does not present this as an IRT or exam score.
  const points=correct*50,rate=Math.round(correct/20*100),earned=correct*10+(points>=600?40:0);
  profile.xp=(profile.xp||0)+earned;
  const attempt={date:localDateISO(0),total:20,correct,blank,points,rate,seconds:used,timeUp,algoCorrect,secCorrect,details};
  profile.bFinalHistory=[attempt,...(profile.bFinalHistory||[])].slice(0,20);lastBFinalAttempt=attempt;saveProfile();

  document.getElementById('bFinalExam')?.classList.remove('show');document.getElementById('bFinalResult')?.classList.add('show');
  renderBFinalResult(attempt,earned);
}
